input.command:
grep -E "rules (successfully )?loaded|rule files|Error|Warning" /var/log/suricata/suricata.log | tail; 
nft flush chain inet filter forward 2>&1 >/dev/null; nft -f - <<'EOF'
table inet filter {
	chain forward {
		iifname "eth1" oifname "eth2" ip saddr 192.168.10.0/24 tcp dport 80 queue num 0
		iifname "eth2" oifname "eth1" ip daddr 192.168.10.0/24 tcp sport 80 queue num 0
		ct state established,related accept
		iifname "eth1" oifname "eth2" accept
	}
}
EOF
nft list chain inet filter forward

